INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (49, 'さむらい館', 'house09.jpg', '人気の動物園へのアクセス抜群！キッズスペースやファミリー向け大型ルーム完備で、小さなお子様連れに優しいお宿です。', 6000, 5, '095-0019', '北海道士別市大通東X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (50, 'さむらい山荘', 'house10.jpg', 'オホーツク海の流氷観光に最適。冷えた体を芯から温める天然温泉と、カニやイクラが山盛りの豪華海鮮丼が自慢。', 9500, 4, '099-0423', '北海道紋別郡遠軽町若松X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (51, 'さむらいの家', 'house01.jpg', '十勝平野の広大な農場の中にあるファームステイ型の宿。乗馬体験やトラクターツアーなど、北海道ならではの体験を。', 7000, 4, '089-0533', '北海道中川郡幕別町札内新北町X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (52, 'サムライの宿', 'house02.jpg', '極上のパウダースノーを目当てに世界中からスキーヤーが集まる宿。リフト券付きのお得な連泊プランをご用意しています。', 4800, 3, '049-3514', '北海道山越郡長万部町富野X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (53, 'ペンション サムライ', 'house03.jpg', '新千歳空港から車で15分。早朝フライトの前泊や、北海道旅行の最終日の拠点として非常に便利な、コスパ最強の立地です。', 5000, 2, '066-0018', '北海道千歳市旭ヶ丘X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (54, 'サムライ荘', 'house04.jpg', '札幌・大通公園に近く、雪まつりやイベント参加に絶好のロケーション。清潔感のあるカプセルタイプで一人旅に最適。', 3500, 1, '003-0804', '北海道札幌市白石区菊水四条X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (55, 'ゲストハウス サムライ', 'house05.jpg', '小樽のレトロな運河沿いにあるゲストハウス。1階はお洒落なカフェバーになっており、地元の人との交流も楽しめます。', 3800, 6, '042-0908', '北海道函館市銅山町X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (56, 'サムライ屋', 'house06.jpg', '名湯の地獄谷から引いた濃厚な硫黄泉が自慢。豊かな自然に囲まれ、四季折々の雪景色を楽しみながら湯浴みを。', 11000, 4, '050-0061', '北海道室蘭市八丁平X-XX-XX', '012-345-678');
INSERT IGNORE INTO houses (id, name, image_name, description, price, capacity, postal_code, address, phone_number) VALUES (57, '民宿 サムライ', 'house07.jpg', '知床の大自然をガイドするネイチャーツアー付きプランが人気。運が良ければキタキツネやエゾシカとの出会いが待っています。', 6500, 3, '059-0027', '北海道登別市青葉町X-XX-XX', '012-345-678');
